    mcq('Q_CI_105', CI, 'APPLY', 2, 'ทำไมผนังหัวใจห้องล่างซ้ายจึงหนากว่าห้องอื่น?', ['ต้องบีบตัวแรงพอส่งเลือดไปทั่วร่างกาย', 'ต้องรับเลือดจากปอดปริมาณมาก', 'เป็นที่สร้างเม็ดเลือดแดง', 'เพื่อป้องกันการติดเชื้อ'], 'a',
        'ห้องล่างซ้ายส่งเลือดในวงจรร่างกายซึ่งยาวและมีแรงต้านมาก จึงต้องมีกล้ามเนื้อหนาที่สุด ห้องล่างขวาส่งเลือดไปปอดซึ่งใกล้กว่า ผนังจึงบางกว่า', ['CDX_HEART_VENTRICLE']),
    mcq('Q_CI_106', CI, 'UNDERSTAND', 2, '"การหมุนเวียนเลือดสองวงจร" ของมนุษย์หมายถึงข้อใด?', ['เลือดผ่านหัวใจ 2 ครั้งต่อรอบ: วงจรปอดและวงจรร่างกาย', 'มีหัวใจ 2 ดวง', 'เลือดไหลไปและกลับในหลอดเลือดเดียวกัน', 'เลือดแดงและเลือดดำไหลในคนละหัวใจ'], 'a',
        'วงจรปอด: หัวใจขวา → ปอด → หัวใจซ้าย · วงจรร่างกาย: หัวใจซ้าย → ร่างกาย → หัวใจขวา เลือดจึงผ่านหัวใจสองครั้งในหนึ่งรอบ', ['CDX_HEART_ATRIUM']),
    mcq('Q_CI_107', CI, 'ANALYZE', 2, 'ข้อใดเป็นลักษณะของหลอดเลือดดำ เมื่อเทียบกับหลอดเลือดแดง?', ['ผนังบางกว่า ความดันต่ำกว่า และมีลิ้นกันเลือดไหลย้อน', 'ผนังหนากว่าและยืดหยุ่นมาก', 'ความดันสูงกว่า', 'แลกเปลี่ยนแก๊สกับเซลล์โดยตรง'], 'a',
        'เลือดในหลอดเลือดดำความดันต่ำ จึงอาศัยลิ้นและการบีบของกล้ามเนื้อรอบ ๆ ช่วยดันเลือดกลับหัวใจ ส่วนหลอดเลือดแดงผนังหนา ยืดหยุ่น รับแรงดันสูง', ['CDX_VEIN', 'CDX_ARTERY']),
    mcq('Q_CI_108', CI, 'REMEMBER', 1, 'การแลกเปลี่ยนสารระหว่างเลือดกับเซลล์เกิดขึ้นที่หลอดเลือดชนิดใด?', ['หลอดเลือดฝอย', 'เอออร์ตา', 'หลอดเลือดดำใหญ่', 'หลอดเลือดแดงพัลโมนารี'], 'a',
        'หลอดเลือดฝอยมีผนังเซลล์ชั้นเดียว แตกแขนงแทรกทั่วเนื้อเยื่อ ทำให้ O₂ สารอาหาร CO₂ และของเสียแพร่ผ่านได้ง่าย', ['CDX_CAPILLARY']),
    mcq('Q_CI_109', CI, 'APPLY', 2, 'ความดันเลือด 120/80 มิลลิเมตรปรอท ตัวเลข 120 หมายถึงอะไร?', ['ความดันขณะหัวใจห้องล่างบีบตัว (ซิสโทลี)', 'ความดันขณะหัวใจคลายตัว', 'อัตราการเต้นของหัวใจต่อนาที', 'ปริมาณเลือดที่สูบต่อครั้ง'], 'a',
        'ค่าบนคือความดันซิสโทลีขณะห้องล่างบีบตัว ค่าล่างคือความดันไดแอสโทลีขณะหัวใจคลายตัว ความดันสูงเกินเป็นเวลานานทำให้หลอดเลือดและหัวใจเสียหาย', ['CDX_ARTERY']),
    tf('Q_CI_110', CI, 'UNDERSTAND', 1, 'ชีพจรที่จับได้ที่ข้อมือเกิดจากหลอดเลือดแดงขยายตัวตามจังหวะการบีบตัวของหัวใจ', 'T',
       'ถูก! ทุกครั้งที่ห้องล่างซ้ายบีบเลือดเข้าเอออร์ตา คลื่นความดันจะทำให้ผนังหลอดเลือดแดงขยายตัว จับได้เป็นชีพจรที่ข้อมือหรือลำคอ', ['CDX_ARTERY']),
    mcq('Q_BD_101', BD, 'UNDERSTAND', 1, 'เม็ดเลือดแดงของมนุษย์มีลักษณะใดที่ช่วยลำเลียง O₂ ได้ดี?', ['ไม่มีนิวเคลียส รูปร่างเว้าสองด้าน และมีฮีโมโกลบินมาก', 'มีนิวเคลียสขนาดใหญ่', 'เคลื่อนที่ได้เองด้วยแฟลเจลลัม', 'มีไมโทคอนเดรียจำนวนมาก'], 'a',
        'เม็ดเลือดแดงที่เจริญเต็มที่ไม่มีนิวเคลียส จึงบรรจุฮีโมโกลบินได้มาก รูปร่างเว้าสองด้านเพิ่มพื้นที่ผิวในการแพร่ของแก๊ส และยืดหยุ่นผ่านหลอดเลือดฝอยได้', ['CDX_RBC']),
    mcq('Q_BD_102', BD, 'REMEMBER', 1, 'ส่วนประกอบใดของเลือดช่วยให้เลือดแข็งตัวเมื่อเกิดบาดแผล?', ['เกล็ดเลือด', 'เม็ดเลือดแดง', 'เม็ดเลือดขาว', 'น้ำในพลาสมา'], 'a',
        'เกล็ดเลือดรวมตัวอุดบาดแผลและปล่อยสารกระตุ้นให้ไฟบริโนเจนในพลาสมาเปลี่ยนเป็นเส้นใยไฟบริน ดักเม็ดเลือดจนเป็นลิ่มเลือด', ['CDX_BLOOD_PARTS']),
    mcq('Q_BD_103', BD, 'REMEMBER', 1, 'พลาสมามีปริมาณประมาณเท่าใดของเลือด และประกอบด้วยอะไรเป็นส่วนใหญ่?', ['ประมาณ 55% ส่วนใหญ่เป็นน้ำ', 'ประมาณ 10% ส่วนใหญ่เป็นโปรตีน', 'ประมาณ 90% ส่วนใหญ่เป็นเม็ดเลือดแดง', 'ประมาณ 45% ส่วนใหญ่เป็นไขมัน'], 'a',
        'พลาสมาประมาณ 55% ของเลือด มีน้ำราว 90% และละลายโปรตีน กลูโคส เกลือแร่ ฮอร์โมน และของเสีย ส่วนอีก 45% คือเซลล์เม็ดเลือด', ['CDX_BLOOD_PARTS']),
    mcq('Q_BD_104', BD, 'APPLY', 2, 'คนหมู่เลือด O มักถูกเรียกว่า "ผู้ให้สากล" เพราะเหตุใด?', ['เม็ดเลือดแดงไม่มีแอนติเจน A และ B จึงไม่ถูกแอนติบอดีของผู้รับจับ', 'พลาสมาไม่มีแอนติบอดีใดเลย', 'มีแอนติเจนทั้ง A และ B', 'มีเลือดมากกว่าคนอื่น'], 'a',
        'เมื่อให้เลือดจะพิจารณาแอนติเจนบนเม็ดเลือดแดงของผู้ให้ หมู่ O ไม่มีแอนติเจน A และ B จึงไม่ถูกจับกลุ่มตกตะกอน (ในทางปฏิบัติต้องตรวจหมู่ Rh และความเข้ากันได้ด้วย)', ['CDX_BLOOD_PARTS']),
    mcq('Q_BD_105', BD, 'ANALYZE', 3, 'คนหมู่เลือด A จะมีแอนติบอดีชนิดใดในพลาสมา?', ['แอนติบอดี B (anti-B)', 'แอนติบอดี A (anti-A)', 'ทั้ง anti-A และ anti-B', 'ไม่มีแอนติบอดีเลย'], 'a',
        'ร่างกายไม่สร้างแอนติบอดีต่อแอนติเจนของตนเอง หมู่ A มีแอนติเจน A จึงมี anti-B หมู่ B มี anti-A หมู่ O มีทั้งสองชนิด และหมู่ AB ไม่มีทั้งสอง', ['CDX_BLOOD_PARTS']),
    mcq('Q_BD_106', BD, 'UNDERSTAND', 2, 'ระบบน้ำเหลืองมีหน้าที่สำคัญข้อใด?', ['นำของเหลวระหว่างเซลล์กลับสู่กระแสเลือด และกรองเชื้อโรคที่ต่อมน้ำเหลือง', 'สูบฉีดเลือดแทนหัวใจ', 'สร้างน้ำย่อย', 'ขับปัสสาวะ'], 'a',
        'ของเหลวที่ซึมออกจากหลอดเลือดฝอยถูกเก็บเข้าท่อน้ำเหลืองแล้วไหลกลับสู่หลอดเลือดดำ ระหว่างทางผ่านต่อมน้ำเหลืองซึ่งมีเม็ดเลือดขาวคอยดักจับเชื้อโรค', ['CDX_IMMUNE_SYSTEM']),
    mcq('Q_IM_101', IM, 'REMEMBER', 1, 'ด่านแรกในการป้องกันเชื้อโรคของร่างกายคือข้อใด?', ['ผิวหนัง เมือก และน้ำย่อย/กรดในกระเพาะ', 'แอนติบอดี', 'เซลล์ทีพิฆาต', 'วัคซีน'], 'a',
        'ภูมิคุ้มกันแบบไม่จำเพาะด่านแรกคือสิ่งกีดขวาง เช่น ผิวหนัง เมือก ขนจมูก น้ำตา (มีไลโซไซม์) และกรดในกระเพาะ ป้องกันเชื้อไม่ให้เข้าสู่ร่างกาย', ['CDX_IMMUNE_SYSTEM']),
    mcq('Q_IM_102', IM, 'UNDERSTAND', 1, 'แมโครฟาจทำลายเชื้อโรคด้วยวิธีใด?', ['ฟาโกไซโทซิส (กลืนกินแล้วย่อยด้วยไลโซโซม)', 'สร้างแอนติบอดี', 'ปล่อยฮอร์โมน', 'สังเคราะห์ด้วยแสง'], 'a',
        'แมโครฟาจและนิวโทรฟิลเป็นฟาโกไซต์ ยื่นเยื่อหุ้มล้อมเชื้อเข้าเซลล์แล้วรวมกับไลโซโซมเพื่อย่อย แมโครฟาจยังนำชิ้นส่วนเชื้อไปแสดงให้เซลล์ทีรู้จัก', ['CDX_WBC']),
    mcq('Q_IM_103', IM, 'REMEMBER', 1, 'แอนติบอดีสร้างจากเซลล์ใด?', ['พลาสมาเซลล์ที่เปลี่ยนแปลงมาจากเซลล์บี', 'เซลล์ทีพิฆาต', 'เม็ดเลือดแดง', 'เกล็ดเลือด'], 'a',
        'เมื่อเซลล์บีพบแอนติเจนที่ตรงกับตัวรับและได้รับการกระตุ้นจากเซลล์ทีผู้ช่วย จะแบ่งตัวเป็นพลาสมาเซลล์ที่หลั่งแอนติบอดี และเซลล์บีความจำ', ['CDX_WBC']),
    mcq('Q_IM_104', IM, 'UNDERSTAND', 2, 'เซลล์ทีพิฆาต (Cytotoxic T cell) ทำหน้าที่ใด?', ['ทำลายเซลล์ของร่างกายที่ติดเชื้อไวรัสหรือเซลล์มะเร็ง', 'สร้างแอนติบอดี', 'กลืนกินแบคทีเรียในเลือด', 'ช่วยให้เลือดแข็งตัว'], 'a',
        'ไวรัสซ่อนอยู่ในเซลล์ แอนติบอดีเข้าไม่ถึง เซลล์ทีพิฆาตจึงจดจำเซลล์ที่แสดงแอนติเจนของไวรัสแล้วทำลายทั้งเซลล์', ['CDX_WBC']),
    mcq('Q_IM_105', IM, 'ANALYZE', 3, 'เชื้อ HIV ทำให้ภูมิคุ้มกันบกพร่องรุนแรงเพราะทำลายเซลล์ใดเป็นหลัก?', ['เซลล์ทีผู้ช่วย', 'เม็ดเลือดแดง', 'เกล็ดเลือด', 'เซลล์ผิวหนัง'], 'a',
        'เซลล์ทีผู้ช่วยเป็นตัวกลางที่กระตุ้นทั้งเซลล์บีและเซลล์ทีพิฆาต เมื่อถูก HIV ทำลายจนเหลือน้อย ระบบภูมิคุ้มกันจำเพาะจึงล่มทั้งระบบ เกิดโรคเอดส์และติดเชื้อฉวยโอกาส', ['CDX_WBC']),
    mcq('Q_IM_106', IM, 'ANALYZE', 2, 'การฉีดวัคซีนต่างจากการฉีดเซรุ่ม (แอนติบอดีสำเร็จรูป) อย่างไร?', ['วัคซีนทำให้ร่างกายสร้างภูมิคุ้มกันเอง (active) อยู่ได้นาน · เซรุ่มให้ภูมิคุ้มกันรับมา (passive) ได้ผลทันทีแต่อยู่ไม่นาน', 'วัคซีนได้ผลทันทีแต่อยู่ไม่นาน', 'ทั้งสองอย่างคือสิ่งเดียวกัน', 'เซรุ่มทำให้เกิดเซลล์ความจำ'], 'a',
        'วัคซีนคือแอนติเจนที่ไม่ก่อโรค ร่างกายตอบสนองและสร้างเซลล์ความจำ ส่วนเซรุ่ม (เช่น เซรุ่มแก้พิษงู) คือแอนติบอดีสำเร็จรูป ใช้รักษาเร่งด่วนแต่หมดไปภายในไม่กี่สัปดาห์', ['CDX_VACCINE']),
    mcq('Q_IM_107', IM, 'APPLY', 2, 'ทำไมเมื่อได้รับเชื้อชนิดเดิมเป็นครั้งที่สอง ร่างกายจึงตอบสนองได้เร็วและแรงกว่าครั้งแรก?', ['มีเซลล์ความจำที่จดจำแอนติเจนนั้นไว้แล้ว', 'เชื้อโรคอ่อนแอลง', 'มีเม็ดเลือดแดงมากขึ้น', 'ผิวหนังหนาขึ้น'], 'a',
        'หลังการติดเชื้อหรือรับวัคซีน จะมีเซลล์บีและเซลล์ทีความจำอยู่ได้นาน เมื่อพบเชื้อเดิมจึงตอบสนองทุติยภูมิได้เร็ว สร้างแอนติบอดีมากกว่าเดิม หลายครั้งจึงไม่ป่วย', ['CDX_VACCINE']),
    mcq('Q_IM_108', IM, 'EVALUATE', 3, 'การใช้ยาปฏิชีวนะพร่ำเพรื่อหรือกินไม่ครบตามแพทย์สั่ง ทำให้เกิดเชื้อดื้อยาได้อย่างไร?', ['ยาคัดเลือกให้แบคทีเรียที่ทนยาได้รอดและเพิ่มจำนวนแทนที่', 'ยาทำให้แบคทีเรียกลายพันธุ์ตามที่ต้องการ', 'ยาทำให้ไวรัสกลายเป็นแบคทีเรีย', 'ยาเพิ่มภูมิคุ้มกันมากเกินไป'], 'a',
        'ในประชากรแบคทีเรียมีบางเซลล์ที่ทนยาได้อยู่แล้วโดยบังเอิญ เมื่อใช้ยาผิดวิธี เซลล์ที่ไวต่อยาตาย ส่วนเซลล์ดื้อยารอดและแพร่พันธุ์ — นี่คือการคัดเลือกโดยธรรมชาติ ยาปฏิชีวนะยังไม่มีผลกับไวรัสเลย', ['CDX_SUPERBUG']),
